#!/usr/bin/env swift

import Foundation

// Simple command-line argument parsing
struct Arguments {
    var files: [String] = []
    var threshold: Int = 3
    var staged: Bool = false
    var types: String = "all"
    var help: Bool = false
}

func parseArguments() -> Arguments {
    var args = Arguments()
    var skipNext = false
    let commandArgs = CommandLine.arguments.dropFirst() // Skip script name

    for (index, arg) in commandArgs.enumerated() {
        if skipNext {
            skipNext = false
            continue
        }

        switch arg {
        case "--threshold":
            if index + 1 < commandArgs.count {
                args.threshold = Int(commandArgs[index + 1]) ?? 3
                skipNext = true
            }
        case "--staged":
            args.staged = true
        case "--types":
            if index + 1 < commandArgs.count {
                args.types = commandArgs[index + 1]
                skipNext = true
            }
        case "--help", "-h":
            args.help = true
        default:
            if !arg.starts(with: "--") {
                args.files.append(arg)
            }
        }
    }

    return args
}

func printHelp() {
    print("""
    Usage: check-emoji-usage.swift [OPTIONS] [FILES...]

    Monitor emoji usage in code and documentation files to enforce visual attention guidelines

    Options:
        --threshold N    Warning threshold for emoji count (default: 3)
        --staged        Check staged files only (git)
        --types TYPE    File types to check: swift, sh, md, all (default: all)
        --help, -h      Show this help message

    Examples:
        check-emoji-usage.swift file.swift
        check-emoji-usage.swift --staged --threshold 5
        check-emoji-usage.swift --types swift *.swift
    """)
}

struct EmojiAnalysisResult {
    let filepath: String
    let count: Int
    let emojis: [String]
}

func getStagedFiles(types: String) -> [String] {
    let process = Process()
    process.launchPath = "/usr/bin/git"
    process.arguments = ["diff", "--cached", "--name-only", "--diff-filter=ACM"]

    let pipe = Pipe()
    process.standardOutput = pipe
    process.launch()
    process.waitUntilExit()

    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    guard let output = String(data: data, encoding: .utf8) else {
        print("Error: Failed to decode git output as UTF-8. Data size: \(data.count) bytes")
        exit(1)
    }

    let allowedExtensions = getAllowedExtensions(types: types)

    return output.components(separatedBy: .newlines)
        .filter { filename in
            !filename.isEmpty && allowedExtensions.contains { filename.hasSuffix($0) }
        }
        .map { String($0) }
}

func getAllowedExtensions(types: String) -> [String] {
    switch types.lowercased() {
    case "swift":
        return [".swift"]
    case "sh":
        return [".sh"]
    case "md":
        return [".md"]
    case "all":
        return [".swift", ".sh", ".md"]
    default:
        return [".swift", ".sh", ".md"]
    }
}

func analyzeFile(at filepath: String) -> EmojiAnalysisResult? {
    do {
        let content = try String(contentsOfFile: filepath, encoding: .utf8)

        // Determine file type and apply appropriate filtering
        let filteredContent: String
        if filepath.hasSuffix(".md") {
            filteredContent = filterMarkdownContent(content, filepath: filepath)
        } else {
            filteredContent = content
        }

        let (count, emojis) = countEmojis(in: filteredContent)

        // Only return result if emojis were found
        return count > 0 ? EmojiAnalysisResult(filepath: filepath, count: count, emojis: emojis) : nil
    } catch {
        // Handle different types of file reading errors with specific diagnostics
        let nsError = error as NSError
        if nsError.code == NSFileReadNoSuchFileError {
            print("Error: File not found: \(filepath)")
        } else if nsError.code == NSFileReadNoPermissionError {
            print("Error: Permission denied reading file: \(filepath)")
        } else {
            print("Error reading file '\(filepath)': \(error.localizedDescription)")
        }
        return nil
    }
}

func filterMarkdownContent(_ content: String, filepath: String) -> String {
    // Skip instruction files that document emoji usage
    let instructionFiles = [
        "copilot-instructions.md",
        "ai-instructions.md",
        "CLAUDE.md",
        "copilot-ios-development-instructions.md"
    ]

    let filename = URL(fileURLWithPath: filepath).lastPathComponent
    if instructionFiles.contains(filename) {
        // For instruction files, only check non-documentation lines
        return filterInstructionFileContent(content)
    }

    var filteredLines: [String] = []
    var inCodeBlock = false

    for line in content.components(separatedBy: .newlines) {
        // Toggle code block state
        if line.starts(with: "```") {
            inCodeBlock.toggle()
            continue
        }

        // Skip lines in code blocks
        if inCodeBlock {
            continue
        }

        // Skip lines that are clearly documenting emoji replacements
        if isEmojiDocumentationLine(line) {
            continue
        }

        filteredLines.append(line)
    }

    return filteredLines.joined(separator: "\n")
}

func filterInstructionFileContent(_ content: String) -> String {
    var filteredLines: [String] = []
    var inEmojiSection = false
    var inCodeBlock = false

    for line in content.components(separatedBy: .newlines) {
        // Toggle code block state
        if line.starts(with: "```") {
            inCodeBlock.toggle()
            continue
        }

        // Skip lines in code blocks
        if inCodeBlock {
            continue
        }

        // Detect emoji documentation sections
        if line.lowercased().contains("emoji replacement") ||
           line.lowercased().contains("emoji usage") ||
           line.lowercased().contains("textual representation") {
            inEmojiSection = true
            continue
        }

        // End of emoji section (usually at next heading)
        if inEmojiSection && (line.starts(with: "#") || line.starts(with: "##")) &&
           !line.lowercased().contains("emoji") {
            inEmojiSection = false
        }

        // Skip lines in emoji documentation sections
        if inEmojiSection {
            continue
        }

        // Skip lines that document emoji replacements
        if isEmojiDocumentationLine(line) {
            continue
        }

        filteredLines.append(line)
    }

    return filteredLines.joined(separator: "\n")
}

func isEmojiDocumentationLine(_ line: String) -> Bool {
    // Pattern for emoji replacement documentation (e.g., "`📝` → `※`")
    let replacementPattern = #"`[^`]+`\s*[→←↔︎]\s*`[^`]+`"#
    if line.range(of: replacementPattern, options: .regularExpression) != nil {
        return true
    }

    // Lines listing alternative symbols
    if line.contains("✓ ✗ → ← ↑ ↓ ⚠") ||
       line.contains("※ • ▪ ▫ ■ □ ▶") {
        return true
    }

    // Lines talking about emojis
    let emojiDiscussionPatterns = [
        "emoji",
        "emoticon",
        "unicode symbol",
        "textual representation",
        "visual noise",
        "alternative symbol"
    ]

    let lowercasedLine = line.lowercased()
    for pattern in emojiDiscussionPatterns {
        if lowercasedLine.contains(pattern) {
            return true
        }
    }

    return false
}

func countEmojis(in text: String) -> (count: Int, emojis: [String]) {
    // Unicode ranges for emojis
    let emojiRanges: [ClosedRange<UInt32>] = [
        0x1F600...0x1F64F, // emoticons
        0x1F300...0x1F5FF, // symbols & pictographs
        0x1F680...0x1F6FF, // transport & map symbols
        0x1F1E0...0x1F1FF, // flags (iOS)
        0x2702...0x27B0,   // dingbats
        0x24C2...0x1F251,  // enclosed characters
        0x1F900...0x1F9FF, // supplemental symbols
        0x1F018...0x1F0FF, // playing cards
        0x2600...0x26FF    // miscellaneous symbols
    ]

    // Allowed textual symbols that shouldn't be counted as problematic emojis
    let allowedSymbols = Set("✓✗→←↑↓⚠ℹ★☆◆◇●○※•▪▫■□▶▷◀◁⟳⟲✔✖➔➜➞➟◎")

    var emojis: [String] = []

    for scalar in text.unicodeScalars {
        // Skip if it's an allowed symbol
        if allowedSymbols.contains(Character(scalar)) {
            continue
        }

        // Check if it's in emoji ranges
        if emojiRanges.contains(where: { $0.contains(scalar.value) }) {
            emojis.append(String(scalar))
        }
    }

    return (emojis.count, emojis)
}

// Main execution
func main() {
    let args = parseArguments()

    if args.help {
        printHelp()
        exit(0)
    }

    let filesToCheck = args.staged ? getStagedFiles(types: args.types) : args.files

    guard !filesToCheck.isEmpty else {
        if args.staged {
            exit(0) // No files staged, exit cleanly
        } else {
            print("No files specified")
            exit(1)
        }
    }

    let results = filesToCheck.compactMap { filepath in
        analyzeFile(at: filepath)
    }

    let totalEmojis = results.reduce(0) { $0 + $1.count }
    let filesWithEmojis = results.filter { $0.count > 0 }

    if totalEmojis == 0 {
        print("✓ No problematic emojis found in analyzed files")
        exit(0)
    }

    print("Total emojis found: \(totalEmojis)")
    print("Files containing emojis: \(filesWithEmojis.count)")

    for result in filesWithEmojis {
        print("  \(result.filepath): \(result.count) emojis - \(result.emojis.joined())")
    }

    if totalEmojis > args.threshold {
        print("\n⚠ WARNING: Total emoji count (\(totalEmojis)) exceeds threshold (\(args.threshold))")
        print("Consider reducing emoji usage to avoid diluting user attention.")
        print("\n• Tip: Consider using alternative Unicode symbols that are less visually distracting:")
        print("   ✓ ✗ → ← ↑ ↓ ⚠ ℹ ★ ☆ ◆ ◇ ● ○ ※ • ▪ ▫ ■ □ ▶ ▷ ◀ ◁ ⟳ ⟲ ✔ ✖ ➔ ➜ ➞ ➟")
        print("\nThis check can be bypassed with: git commit --no-verify")
        exit(1)
    }

    exit(0)
}

